    # There are 4 possible 2x2 squares: top-left, top-right, bottom-left, bottom-right

    def count_changes_for_square(top_row, left_col, target_color):
        # Count how many cells need to be changed in a 2x2 square to make all cells target_color
        changes = 0
        for i in range(2):
            for j in range(2):
                if grid[top_row + i][left_col + j] != target_color:
                    changes += 1
        return changes

    # Check each of the 4 possible 2x2 squares
    for top_row in range(2):
        for left_col in range(2):
            # For this 2x2 square, check if we can make all cells 'B' with at most 1 change
            if count_changes_for_square(top_row, left_col, 'B') <= 1:
                return True
            # For this 2x2 square, check if we can make all cells 'W' with at most 1 change
            if count_changes_for_square(top_row, left_col, 'W') <= 1:
                return True

