    lower_chars = set()
    upper_chars = set()

    # Separate lowercase and uppercase characters
    for char in word:
        if char.islower():
            lower_chars.add(char)
        else:
            upper_chars.add(char.lower())  # Store as lowercase for comparison

    # Count special letters (those that appear in both cases)
