def lastNonEmptyString(s):
    # Count frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Characters that will remain just before the last operation
    # are those with maximum frequency (they'll be removed in the last pass)
    result_chars = []
    for char in s:
        if freq[char] == max_freq and char not in result_chars:
            result_chars.append(char)

    # Construct the result by preserving the order from original string
    # but only including characters that have max frequency
    result = ""
    for char in s:
        if freq[char] == max_freq and char not in result:
            result += char

    return result
```

