def solve():
    import sys
    from itertools import permutations

    def read_polyomino(lines, start):
        grid = []
        for i in range(4):
            row = lines[start + i].strip()
            grid.append(row)
        return grid

    def get_cells(poly):
        cells = []
        for i in range(4):
            for j in range(4):
                if poly[i][j] == '#':
                    cells.append((i, j))
        return cells

    def normalize(cells):
        if not cells:
            return cells
        min_i = min(i for i, j in cells)
        min_j = min(j for i, j in cells)
        return sorted([(i - min_i, j - min_j) for i, j in cells])

    def rotate90(cells):
        return [(j, 3 - i) for i, j in cells]

    def get_all_rotations(poly_cells):
        rotations = []
        current = poly_cells[:]
        for _ in range(4):
            normalized = normalize(current)
            if normalized not in rotations:
                rotations.append(normalized)
            current = rotate90(current)
        return rotations

    def translate_cells(cells, di, dj):
        return [(i + di, j + dj) for i, j in cells]

    def is_valid_position(cells):
        for i, j in cells:
            if i < 0 or i >= 4 or j < 0 or j >= 4:
                return False
        return True

    def can_place(grid, cells):
        for i, j in cells:
            if grid[i][j] != '.':
                return False
        return True

    def place(grid, cells, char):
        new_grid = [list(row) for row in grid]
        for i, j in cells:
            new_grid[i][j] = char
        return tuple(''.join(row) for row in new_grid)

    def solve_puzzle(polyominoes):
        # Get all possible placements for each polyomino
        all_forms = []
        for poly in polyominoes:
            cells = get_cells(poly)
            base_cells = normalize(cells)
            rotations = get_all_rotations(base_cells)

            placements = []
            for rot in rotations:
                for di in range(4):
                    for dj in range(4):
                        translated = translate_cells(rot, di, dj)
                        if is_valid_position(translated):
                            placements.append(translated)
            all_forms.append(placements)

        # Try all permutations of polyominoes and their placements
        for perm in permutations(range(3)):
            for form0 in all_forms[perm[0]]:
                # Create initial empty grid
                grid = ("....", "....", "....", "....")

                # Place first polyomino
                if not can_place(grid, form0):
                    continue
                grid1 = place(grid, form0, '1')

                for form1 in all_forms[perm[1]]:
                    # Place second polyomino
                    if not can_place(grid1, form1):
                        continue
                    grid2 = place(grid1, form1, '2')

                    for form2 in all_forms[perm[2]]:
                        # Place third polyomino and check if the grid is fully filled
                        if not can_place(grid2, form2):
                            continue
                        final_grid = place(grid2, form2, '3')

                        # Check if all cells are filled
                        complete = True
                        for i in range(4):
                            for j in range(4):
                                if final_grid[i][j] == '.':
                                    complete = False
                                    break
                            if not complete:
                                break

                        if complete:
                            return True
        return False

    # Read input
    lines = []
    for line in sys.stdin:
        lines.append(line.strip())

    # Parse the three polyominoes
    polyominoes = []
    for i in range(3):
        poly = read_polyomino(lines, i * 4)
        polyominoes.append(poly)

    # Solve and output result
    if solve_puzzle(polyominoes):
        print("Yes")
    else:
        print("No")

solve()
```

