            if len(row) >= 2 and all(c == row[0] for c in row):
                for j in range(W):
                    if grid[i][j] != '.':
                        marked.add((i, j))

        # Step 2: Check each column
        for j in range(W):
            col = [grid[i][j] for i in range(H) if grid[i][j] != '.']
            # If there are 2+ cookies and all have the same color
            if len(col) >= 2 and all(c == col[0] for c in col):
                for i in range(H):
                    if grid[i][j] != '.':
                        marked.add((i, j))

        # If no cookies are marked, terminate
        if not marked:
