def solve():
    # Read the 3x3 grid
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)

    # All possible winning lines (rows, columns, diagonals)
    lines = [
        [(0,0), (0,1), (0,2)], # row 1
        [(1,0), (1,1), (1,2)], # row 2
        [(2,0), (2,1), (2,2)], # row 3
        [(0,0), (1,0), (2,0)], # col 1
        [(0,1), (1,1), (2,1)], # col 2
        [(0,2), (1,2), (2,2)], # col 3
        [(0,0), (1,1), (2,2)], # diag 1
        [(0,2), (1,1), (2,0)]  # diag 2
    ]

    def check_winner(colors):
        # Check if any line is fully occupied by same color
        for line in lines:
            colors_in_line = [colors[r][c] for r, c in line]
            if colors_in_line == ['R', 'R', 'R']:
                return 'Takahashi'
            if colors_in_line == ['B', 'B', 'B']:
                return 'Aoki'
        return None

    def get_available_moves(colors):
        moves = []
        for i in range(3):
            for j in range(3):
                if colors[i][j] == 'W':
                    moves.append((i, j))
        return moves

    def minimax(colors, scores, turn, alpha, beta):
        # Check for immediate winner
        winner = check_winner(colors)
        if winner:
            return (float('inf') if winner == 'Takahashi' else float('-inf'), None)

        # Check if board is full
        available = get_available_moves(colors)
        if not available:
            # Game ends by score
            if scores[0] > scores[1]:
                return (float('inf'), None)  # Takahashi wins
            elif scores[0] < scores[1]:
                return (float('-inf'), None)  # Aoki wins
            else:
                # Since sum is guaranteed to be odd, scores can't be equal
                # But just in case:
                return (float('inf') if scores[0] > scores[1] else float('-inf'), None)

        if turn == 0:  # Takahashi's turn (maximizing)
            best_value = float('-inf')
            best_move = None
            for i, j in available:
                # Make move
                new_colors = [row[:] for row in colors]
                new_colors[i][j] = 'R'
                new_scores = scores[:]
                new_scores[0] += grid[i][j]

                # Check if this move creates a winning line
                winner = check_winner(new_colors)
                if winner == 'Takahashi':
                    return (float('inf'), (i, j))

                value, _ = minimax(new_colors, new_scores, 1, alpha, beta)
                if value > best_value:
                    best_value = value
                    best_move = (i, j)

                alpha = max(alpha, best_value)
                if beta <= alpha:
                    break

            return (best_value, best_move)
        else:  # Aoki's turn (minimizing)
            best_value = float('inf')
            best_move = None
            for i, j in available:
                # Make move
                new_colors = [row[:] for row in colors]
                new_colors[i][j] = 'B'
                new_scores = scores[:]
                new_scores[1] += grid[i][j]

                # Check if this move creates a winning line
                winner = check_winner(new_colors)
                if winner == 'Aoki':
                    return (float('-inf'), (i, j))

                value, _ = minimax(new_colors, new_scores, 0, alpha, beta)
                if value < best_value:
                    best_value = value
                    best_move = (i, j)

                beta = min(beta, best_value)
                if beta <= alpha:
                    break

            return (best_value, best_move)

    # Initialize game state
    colors = [['W' for _ in range(3)] for _ in range(3)]
    scores = [0, 0]  # [Takahashi, Aoki]

    # Use minimax to determine winner
    result, _ = minimax(colors, scores, 0, float('-inf'), float('inf'))

    if result >= 0:
        print("Takahashi")
    else:
        print("Aoki")

solve()
