def minimumChanges(s, k):
    n = len(s)

    # Precompute the cost to make each substring a semi-palindrome
    def get_semi_palindrome_cost(substring):
        length = len(substring)
        if length == 1:
            return float('inf')  # Single character cannot be semi-palindrome

        min_cost = float('inf')

        # Try all possible divisors d where 1 <= d < length and length % d == 0
        for d in range(1, length):
            if length % d != 0:
                continue

            cost = 0
            # For each residue class modulo d, check if it forms a palindrome
            for r in range(d):
                # Get characters at positions with index ≡ r (mod d)
                chars = []
                for i in range(r, length, d):
                    chars.append(substring[i])

                # Check how many changes needed to make this sequence a palindrome
                m = len(chars)
                for j in range(m // 2):
                    if chars[j] != chars[m - 1 - j]:
                        cost += 1

            min_cost = min(min_cost, cost)

        return min_cost

    # Precompute cost for all substrings
    cost = {}
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            cost[(i, j)] = get_semi_palindrome_cost(substring)

    # Dynamic programming: dp[i][p] = minimum cost to partition s[:i] into p parts
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            # Try all possible starting positions of the last substring
            for j in range(p - 1, i):
                if dp[j][p - 1] != INF:
                    c = cost.get((j, i), INF)
                    if c != INF:
                        dp[i][p] = min(dp[i][p], dp[j][p - 1] + c)

    return dp[n][k]
```

