def countBeautifulSubstrings(s, k):
    vowels_set = set('aeiou')
    n = len(s)
    count = 0

    # Check all possible substrings
    for i in range(n):
        vowels = 0
        consonants = 0
        for j in range(i, n):
            # Count vowels and consonants incrementally
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # Check if the current substring is beautiful
            if vowels == consonants and (vowels * consonants) % k == 0:
                count += 1

    return count
