    events = []
    index = 1
    for i in range(n):
        t = int(data[index]); x = int(data[index+1]); index += 2
        events.append((t, x))

    # Count monster occurrences per type
    monster_count = [0] * (n + 1)
    potion_events = []  # store indices where potion is found

    for i, (t, x) in enumerate(events):
        if t == 1:
            potion_events.append(i)
        else:
            monster_count[x] += 1

    # Check feasibility: can we have enough potions?
    # For each type, we need at least as many potions as monsters of that type
    potion_needed = [0] * (n + 1)
    for i, (t, x) in enumerate(events):
        if t == 2:
            potion_needed[x] += 1

    # Simulate to check if it's possible and compute minimal K
    # We will try to greedily minimize the maximum number of potions held

    def simulate(decisions):
        # decisions[i] = True if we pick up the potion at the i-th event (only for t=1 events)
        inventory = [0] * (n + 1)
        max_potions = 0
        pot_idx = 0

        for t, x in events:
            if t == 1:
                if decisions[pot_idx]:
                    inventory[x] += 1
                pot_idx += 1
            else:  # t == 2
                if inventory[x] <= 0:
