def shortestSubstrings(arr):
    n = len(arr)
    answer = [""] * n

    for i in range(n):
        current_string = arr[i]
        other_strings = arr[:i] + arr[i+1:]

        # Get all substrings of current string, sorted by length then lexicographically
        substrings = []
        for length in range(1, len(current_string) + 1):
            for start in range(len(current_string) - length + 1):
                substr = current_string[start:start + length]
                substrings.append(substr)

        # Find the first (shortest and lexicographically smallest) substring that doesn't appear in any other string
        for substr in substrings:
            found_in_other = False
            for other in other_strings:
                if substr in other:
                    found_in_other = True
                    break

            if not found_in_other:
                answer[i] = substr
                break

    return answer
