    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    L = [int(next(it)) for _ in range(N)]

    # lower bound: at least the maximum word width
    low = max(L)
    # upper bound: all words in one line (sum of widths + spaces)
    high = sum(L) + (N - 1)

    # check if window width W can hold the text in at most M lines
    def feasible(W: int) -> bool:
        lines = 1
        cur = 0
        for w in L:
            if cur == 0:
                cur = w
            else:
                if cur + 1 + w <= W:
                    cur += 1 + w
                else:
                    lines += 1
                    cur = w
                    if lines > M:
                        return False
        return lines <= M

    # binary search for the minimal W
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1

    print(low)

