    n = len(s)

    # Try all possible lengths of t from 1 to n
    for length in range(1, n + 1):
        # Check if n is divisible by length
        if n % length == 0:
            # Get the frequency count of the first segment
            base_freq = {}
            for i in range(length):
                base_freq[s[i]] = base_freq.get(s[i], 0) + 1

            # Check if all segments are anagrams of the first segment
            valid = True
            for i in range(1, n // length):
                segment_freq = {}
                start = i * length
                end = start + length

                # Count frequency in current segment
                for j in range(start, end):
                    segment_freq[s[j]] = segment_freq.get(s[j], 0) + 1

                # Compare with base frequency
                if segment_freq != base_freq:
                    valid = False
                    break

            if valid:
