def maximumStrength(nums, k):
    n = len(nums)

    # dp[i][j][0] = max strength using first i elements, j subarrays, and not having a subarray ending at i-1
    # dp[i][j][1] = max strength using first i elements, j subarrays, and having a subarray ending at i-1
    # We'll use -inf to represent impossible states

    NEG_INF = float('-inf')

    # Use 2D DP for space optimization since we only need previous row
    # dp[j][ended] where j is number of subarrays used, ended indicates if last element was used
    prev_dp = [[NEG_INF, NEG_INF] for _ in range(k + 1)]
    prev_dp[0][0] = 0  # Base case: 0 subarrays, 0 strength

    for i in range(n):
        curr_dp = [[NEG_INF, NEG_INF] for _ in range(k + 1)]

        for j in range(k + 1):
            # Carry forward the state where we don't use nums[i]
            if j > 0:
                # Can extend from either state where we had j-1 subarrays
                if prev_dp[j-1][0] != NEG_INF:
                    curr_dp[j][1] = max(curr_dp[j][1], prev_dp[j-1][0] + nums[i] * (k - j + 1) * ((-1) ** (j+1)))
                if prev_dp[j-1][1] != NEG_INF:
                    curr_dp[j][1] = max(curr_dp[j][1], prev_dp[j-1][1] + nums[i] * (k - j + 1) * ((-1) ** (j+1)))

            # Continue a subarray that includes nums[i]
            if j > 0 and prev_dp[j][1] != NEG_INF:
                curr_dp[j][1] = max(curr_dp[j][1], prev_dp[j][1] + nums[i] * (k - j + 1) * ((-1) ** (j+1)))

            # Start a new subarray at nums[i]
            if j > 0 and prev_dp[j-1][0] != NEG_INF:
                curr_dp[j][1] = max(curr_dp[j][1], prev_dp[j-1][0] + nums[i] * (k - j + 1) * ((-1) ** (j+1)))

            # Don't use nums[i] - carry forward all valid states
            for end_state in range(2):
                if prev_dp[j][end_state] != NEG_INF:
                    curr_dp[j][0] = max(curr_dp[j][0], prev_dp[j][end_state])

        prev_dp = curr_dp

    # Answer is the maximum of all ways to use exactly k subarrays
    return max(prev_dp[k][0], prev_dp[k][1])
