def solve():
    import sys
    from collections import defaultdict

    # Read input
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        print(-1)
        return

    N, M = map(int, lines[0].split())

    # Build directed graph: edge A -> B means A is stronger than B
    stronger_than = defaultdict(set)  # person -> set of people they are stronger than
    weaker_than = defaultdict(set)   # person -> set of people who are stronger than them

    for i in range(1, M + 1):
        if i >= len(lines):
            break
        a, b = map(int, lines[i].split())
        stronger_than[a].add(b)
        weaker_than[b].add(a)

    # Use transitivity to propagate known relations (Floyd-Warshall style)
    # We'll compute the full relation closure
    can_beat = [[False] * (N + 1) for _ in range(N + 1)]

    # Initialize with direct relations
    for a in range(1, N + 1):
        for b in stronger_than[a]:
            can_beat[a][b] = True

    # Apply transitivity (Floyd-Warshall)
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if can_beat[i][k] and can_beat[k][j]:
                    can_beat[i][j] = True

    # Find candidates for strongest programmer
    # A person is strongest if they are stronger than all others
    possible_strongest = []

    for person in range(1, N + 1):
        is_strongest = True
        for other in range(1, N + 1):
            if person != other:
                # We need to know that person > other
                if not can_beat[person][other]:
                    is_strongest = False
                    break
        if is_strongest:
            possible_strongest.append(person)

    # If exactly one strongest programmer, output it; otherwise -1
    if len(possible_strongest) == 1:
        print(possible_strongest[0])
    else:
        print(-1)

