def minOperations(nums, k):
    nums.sort()
    n = len(nums)

    # Find the median index
    # For even length, we take the larger of the two middle elements
    # which is at index n//2 (0-indexed)
    median_idx = n // 2

    median = nums[median_idx]

    if median == k:
        return 0

    operations = 0

    if median < k:
        # Need to increase the median to k
        # All elements from median index onwards that are less than k need to be increased
        for i in range(median_idx, n):
            if nums[i] < k:
                operations += k - nums[i]
    else:
        # Need to decrease the median to k
        # All elements from median index backwards that are greater than k need to be decreased
        for i in range(median_idx + 1):
            if nums[i] > k:
                operations += nums[i] - k

    return operations
