def maxPalindromes(words):
    # Count frequency of each character across all words
    char_count = {}
    for word in words:
        for char in word:
            char_count[char] = char_count.get(char, 0) + 1

    # Sort words by length in ascending order to maximize palindromes
    word_lengths = sorted([len(word) for word in words])

    palindromes = 0
    remaining_chars = char_count.copy()

    for length in word_lengths:
        # Check if we can form a palindrome of this length
        odd_count = 0
        temp_chars = remaining_chars.copy()

        # For a palindrome, at most one character can have odd frequency
        for char, count in temp_chars.items():
            if count % 2 == 1:
                odd_count += 1

        # We need at most 1 odd frequency character for a palindrome
        if odd_count <= 1:
            # We can make a palindrome, use up the characters
            palindromes += 1

            # Remove characters used in this palindrome
            chars_needed = {}
            for i in range(length // 2):  # Half the characters (pairs)
                found = False
                for char, count in temp_chars.items():
                    if count >= 2:
                        chars_needed[char] = chars_needed.get(char, 0) + 2
                        temp_chars[char] -= 2
                        found = True
                        break
                if not found:  # If we can't find enough pairs
                    break

            # Handle middle character for odd-length palindromes
            if length % 2 == 1:
                middle_found = False
                for char, count in temp_chars.items():
                    if count >= 1:
                        chars_needed[char] = chars_needed.get(char, 0) + 1
                        temp_chars[char] -= 1
                        middle_found = True
                        break

                if not middle_found and length > 1:  # Need middle but none available
                    palindromes -= 1  # Can't actually form this palindrome
                    continue

            # Update remaining characters
            for char, used in chars_needed.items():
                remaining_chars[char] -= used
                if remaining_chars[char] == 0:
                    del remaining_chars[char]
        else:
            # Try to see if we can rearrange to make a palindrome of this length
            # Greedily assign characters to form palindrome
            needed_pairs = length // 2
            available_pairs = sum(count // 2 for count in remaining_chars.values())

            if available_pairs >= needed_pairs:
                palindromes += 1

                # Use up the characters
                pairs_used = 0
                chars_to_update = {}

                # Use pairs first
                for char in sorted(remaining_chars.keys()):
                    if pairs_used >= needed_pairs:
                        break
                    can_use_pairs = remaining_chars[char] // 2
                    use_pairs = min(can_use_pairs, needed_pairs - pairs_used)
                    chars_to_update[char] = remaining_chars[char] - (use_pairs * 2)
                    pairs_used += use_pairs

                # Use middle character if needed
                if length % 2 == 1:
                    # Find any remaining character
                    middle_used = False
                    for char, count in remaining_chars.items():
                        if count > chars_to_update.get(char, 0):
                            chars_to_update[char] = chars_to_update.get(char, 0) - 1
                            middle_used = True
                            break

                    if not middle_used and needed_pairs > 0:  # Failed to get middle
                        palindromes -= 1
                        continue

                # Update remaining characters
                for char, new_count in chars_to_update.items():
                    if new_count > 0:
                        remaining_chars[char] = new_count
                    elif char in remaining_chars:
                        del remaining_chars[char]

    return palindromes
