def punishmentNumber(n):
    def can_partition(num_str, target, current_sum):
        if not num_str:
            return current_sum == target

        for i in range(1, len(num_str) + 1):
            prefix = num_str[:i]
            # Avoid numbers with leading zeros (except "0" itself)
            if prefix[0] == '0' and len(prefix) > 1:
                continue

            new_sum = current_sum + int(prefix)
            # Early termination if sum already exceeds target
            if new_sum > target:
                continue

            if can_partition(num_str[i:], target, new_sum):
                return True

        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)

        if can_partition(square_str, i, 0):
            total += square

    return total
