    index = 1
    for i in range(1, n + 1):
        c = int(data[index])
        index += 1
        if c > 0:
            p_list = list(map(int, data[index:index + c]))
            index += c
            prerequisites[i] = p_list
        else:
            prerequisites[i] = []

    # Find all books needed to read book 1 using DFS
    needed_books = set()
    stack = [1]

    while stack:
        book = stack.pop()
        for prereq in prerequisites[book]:
            if prereq not in needed_books:
                needed_books.add(prereq)
                stack.append(prereq)

    # Remove book 1 from the needed books (we only want books excluding book 1)
    if 1 in needed_books:
        needed_books.remove(1)

    # Build dependency graph (reverse: prerequisite -> dependent)
    dependents = defaultdict(list)
    for book in range(1, n + 1):
        for prereq in prerequisites[book]:
            dependents[prereq].append(book)

    # Calculate in-degree for topological sort (number of unfulfilled prerequisites)
    in_degree = {}
    for book in needed_books | {1}:
        in_degree[book] = len([p for p in prerequisites[book] if p in needed_books])

    # Add other books that might be prerequisites but aren't in needed_books yet
    for book in list(needed_books):
        for prereq in prerequisites[book]:
            if prereq not in needed_books and prereq != 1:
                needed_books.add(prereq)
                in_degree[prereq] = len([p for p in prerequisites[prereq] if p in needed_books])

    # Topological sort using Kahn's algorithm
    queue = deque()
    result = []

    # Initialize queue with books that have no prerequisites (among needed books)
    for book in needed_books:
        if in_degree[book] == 0:
            queue.append(book)

    while queue:
        book = queue.popleft()
        result.append(book)

        # Reduce in-degree of dependents
        for dep in dependents[book]:
            if dep in needed_books:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    queue.append(dep)

    print(' '.join(map(str, result)))

solve()
