def shortestBeautifulSubstring(s, k):
    n = len(s)
    min_length = float('inf')
    candidates = []

    # Find all substrings with exactly k ones
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            # If we have exactly k ones, check if this is a potential answer
            if ones_count == k:
                length = j - i + 1
                substring = s[i:j+1]

                if length < min_length:
                    min_length = length
                    candidates = [substring]
                elif length == min_length:
                    candidates.append(substring)
                break  # No need to extend further once we have k ones

    # If no beautiful substring found
    if not candidates:
        return ""

    # Return lexicographically smallest among the shortest ones
    return min(candidates)
