    tiles = []
    for i in range(1, N + 1):
        a, b = map(int, lines[i].split())
        tiles.append((a, b))

    # Total area must match
    total_grid_area = H * W
    used_tiles_area = 0

    # Try all possible subsets of tiles and their arrangements
    def can_fill(grid, row, col, remaining_tiles):
        # Skip filled cells
        while row < H and grid[row][col]:
            col += 1
            if col == W:
                row += 1
                col = 0

        # If we've filled the entire grid
        if row >= H:
            return True

        # Try each remaining tile
        for idx, (a, b) in enumerate(remaining_tiles):
            next_tiles = remaining_tiles[:idx] + remaining_tiles[idx+1:]

            # Try both orientations: (a,b) and (b,a)
            for h, w in [(a, b), (b, a)]:
                # Check if tile fits at current position
                if row + h <= H and col + w <= W:
                    # Check if space is free
                    can_place = True
                    for r in range(row, row + h):
                        for c in range(col, c + w):
                            if grid[r][c]:
                                can_place = False
                                break
                        if not can_place:
                            break

                    if can_place:
                        # Place tile
                        for r in range(row, row + h):
                            for c in range(col, col + w):
                                grid[r][c] = True

                        # Recursively fill the rest
                        if can_fill(grid, row, col, next_tiles):
                            return True

                        # Backtrack
                        for r in range(row, row + h):
                            for c in range(col, col + w):
                                grid[r][c] = False

        return False

    # Try all permutations of tiles
    for perm in permutations(tiles):
        # Start with empty grid
        grid = [[False] * W for _ in range(H)]

        # Try to fill using this permutation (and any prefix of it)
        if can_fill(grid, 0, 0, list(perm)):
            print("Yes")
            return

    print("No")

