def canSortArray(nums):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Group elements by their set bit count and maintain relative order within groups
    groups = []
    current_group = []
    current_bit_count = -1

    for num in nums:
        bit_count = count_set_bits(num)
        if bit_count == current_bit_count:
            current_group.append(num)
        else:
            if current_group:
                groups.append(current_group)
            current_group = [num]
            current_bit_count = bit_count

    # Don't forget the last group
    if current_group:
        groups.append(current_group)

    # Sort each group individually
    for group in groups:
        group.sort()

    # Flatten the groups back into an array
    sorted_by_groups = []
    for group in groups:
        sorted_by_groups.extend(group)

    # Check if the resulting array is sorted in non-decreasing order
    for i in range(1, len(sorted_by_groups)):
        if sorted_by_groups[i] < sorted_by_groups[i-1]:
            return False

    return True
