from typing import List

class DSU:
    """Disjoint Set Union with path compression and union by rank."""
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int) -> None:
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # Precompute smallest prime factor (SPF) for all numbers up to max(nums)
    max_val = max(nums)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:                     # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    dsu = DSU(n)
    prime_to_index = {}                     # prime -> first index containing it

    for i, val in enumerate(nums):
        # Factorize val using the small-prime-factor table
        while val > 1:
            p = spf[val]
            while val % p == 0:
                val //= p
            if p in prime_to_index:
                dsu.union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    # All indices should belong to the same connected component
    root = dsu.find(0)
    for i in range(1, n):
        if dsu.find(i) != root:
            return False
    return True
```

