    data = input().split()

    # Read N and M
    n = int(data[0])
    m = int(data[1])

    sets = []
    index = 2

    for _ in range(n):
        a = int(data[index])
        index += 1
        s = list(map(int, data[index:index + a]))
        index += a
        sets.append(set(s))

    # Check if any set already contains both 1 and M
    for s in sets:
        if 1 in s and m in s:
            print(0)
            return

    # Build graph of connectivity between sets based on common elements
    # We'll use union-find (disjoint set union) to group connected sets
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Create mapping from element to list of set indices containing it
    elem_to_sets = defaultdict(list)
    for i, s in enumerate(sets):
        for elem in s:
            elem_to_sets[elem].append(i)

    # Union all sets that share at least one common element
    for elem, set_indices in elem_to_sets.items():
        for i in range(1, len(set_indices)):
            union(set_indices[0], set_indices[i])

    # Find connected components
    components = defaultdict(list)
    for i in range(n):
        components[find(i)].append(i)

    # For each component, compute the union of all sets in it
    comp_to_elements = {}
    for root in components:
        union_set = set()
        for idx in components[root]:
            union_set |= sets[idx]
        comp_to_elements[root] = union_set

    # Check if there's a component whose union contains both 1 and M
    min_operations = float('inf')

    for root, elements in comp_to_elements.items():
        if 1 in elements and m in elements:
            # Number of operations needed is (number of sets in component - 1)
            operations = len(components[root]) - 1
            min_operations = min(min_operations, operations)

    if min_operations == float('inf'):
        print(-1)
    else:
        print(min_operations)

