                if reel[t % M] == digit:
                    reel_times.append(t)
            if not reel_times:
                break
            times.append(reel_times)

        # If any reel cannot show the digit, skip this digit
        if len(times) != 3:
            continue

        # Try all combinations of stopping times for the three reels
        current_min = float('inf')
        for t1 in times[0]:
            for t2 in times[1]:
                if t2 <= t1:
                    continue
                for t3 in times[2]:
                    if t3 <= t2:
                        continue
                    # The total time is the last stopping time
                    current_min = min(current_min, t3)

                # Also try t1, t3, t2 order
                for t3 in times[2]:
                    if t3 <= t1:
                        continue
                    if t2 > t3:
                        continue
                    current_min = min(current_min, t2)

            # Also try t2, t1, t3 order
            for t2 in times[1]:
                if t2 <= t1:
                    continue
                for t3 in times[2]:
                    if t3 <= t2:
                        continue
                    current_min = min(current_min, t3)

        if current_min != float('inf'):
            min_time = min(min_time, current_min)

